1	import { Bell, Calendar, ArrowRight } from "lucide-react";
2	import { Link } from "react-router-dom";
3	import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
4	import { Button } from "@/components/ui/button";
5	import { Badge } from "@/components/ui/badge";
6	import { Separator } from "@/components/ui/separator";
7	import { useMonitoring } from "@/hooks/use-monitoring";
8	import { useScans } from "@/hooks/use-scans";
9	import type { Scan } from "@/types";
10	
11	interface MonitoringSettingsCardProps {
12	  isPro: boolean;
13	  userEmail?: string;
14	}
15	
16	// Returns "Feb 1" style date for the 1st of next month
17	function getNextScanDate(): string {
18	  const now = new Date();
19	  const next = new Date(now.getFullYear(), now.getMonth() + 1, 1);
20	  return next.toLocaleDateString("en-US", { month: "short", day: "numeric" });
21	}
22	
23	export function MonitoringSettingsCard({ isPro, userEmail }: MonitoringSettingsCardProps) {
24	  const { monitoredUrls } = useMonitoring();
25	  const { data: scans = [] } = useScans();
26	
27	  const monitoredScans = scans.filter(
28	    (s) => s.status === "completed" && monitoredUrls.has(s.url)
29	  );
30	
31	  // Keep only the latest scan per URL
32	  const uniqueMonitored = Object.values(
33	    monitoredScans.reduce<Record<string, Scan>>((acc, scan) => {
34	      if (
35	        !acc[scan.url] ||
36	        new Date(scan.created_at) > new Date(acc[scan.url].created_at)
37	      ) {
38	        acc[scan.url] = scan;
39	      }
40	      return acc;
41	    }, {})
42	  );
43	
44	  if (!isPro) {
45	    return (
46	      <Card className="border-border/50 shadow-none">
47	        <CardHeader>
48	          <div className="flex items-center justify-between">
49	            <div className="flex items-center gap-2">
50	              <Bell className="h-4 w-4 text-muted-foreground" />
51	              <CardTitle className="text-base">Monthly Monitoring</CardTitle>
52	            </div>
53	            <Badge variant="outline" className="border-amber-200 bg-amber-50 text-amber-700 text-xs">
54	              Pro Feature
55	            </Badge>
56	          </div>
57	          <CardDescription>
58	            Automatically re-scan your URLs every month and get alerted when conversion scores drop.
59	          </CardDescription>
60	        </CardHeader>
61	        <CardContent>
62	          <div className="rounded-lg bg-muted/40 p-4 text-sm text-muted-foreground">
63	            Upgrade to Pro to enable monthly score monitoring for your key pages and receive email
64	            alerts when CRO scores drop below your threshold.
65	          </div>
66	          <Button className="mt-4 w-full" asChild>
67	            <Link to="/pricing">Upgrade to Pro</Link>
68	          </Button>
69	        </CardContent>
70	      </Card>
71	    );
72	  }
73	
74	  return (
75	    <Card className="border-border/50 shadow-none">
76	      <CardHeader>
77	        <div className="flex items-center gap-2">
78	          <Bell className="h-4 w-4 text-muted-foreground" />
79	          <CardTitle className="text-base">Monthly Monitoring</CardTitle>
80	        </div>
81	        <CardDescription>
82	          {uniqueMonitored.length} URL{uniqueMonitored.length !== 1 ? "s" : ""} being monitored.
83	          Automated re-scans run on the 1st of each month.
84	        </CardDescription>
85	      </CardHeader>
86	      <CardContent className="space-y-4">
87	        {uniqueMonitored.length === 0 ? (
88	          <div className="rounded-lg border border-dashed border-border/60 p-6 text-center">
89	            <Bell className="mx-auto h-8 w-8 text-muted-foreground/40 mb-2" />
90	            <p className="text-sm text-muted-foreground">No URLs monitored yet.</p>
91	            <p className="text-xs text-muted-foreground/70 mt-1">
92	              Open any report &rarr; menu &rarr; &ldquo;Monitor Monthly&rdquo; to start tracking.
93	            </p>
94	            <Button variant="outline" size="sm" className="mt-3 border-border/50" asChild>
95	              <Link to="/reports">View Reports</Link>
96	            </Button>
97	          </div>
98	        ) : (
99	          <div className="divide-y divide-border/50">
100	            {uniqueMonitored.map((scan) => {
101	              let hostname = scan.url;
102	              try {
103	                hostname = new URL(scan.url).hostname.replace("www.", "");
104	              } catch {
105	                /* keep raw url */
106	              }
107	              return (
108	                <div
109	                  key={scan.id}
110	                  className="flex items-center justify-between py-3 first:pt-0 last:pb-0"
111	                >
112	                  <div className="flex items-center gap-2 min-w-0">
113	                    <Bell className="h-3.5 w-3.5 shrink-0 text-primary" />
114	                    <span className="text-sm truncate">{hostname}</span>
115	                  </div>
116	                  <div className="flex items-center gap-2 shrink-0">
117	                    <div className="flex items-center gap-1 text-xs text-muted-foreground">
118	                      <Calendar className="h-3 w-3" />
119	                      <span>Next: {getNextScanDate()}</span>
120	                    </div>
121	                    <Button variant="ghost" size="sm" asChild className="h-7 px-2">
122	                      <Link to={`/reports/${scan.id}`}>
123	                        <ArrowRight className="h-3.5 w-3.5" />
124	                      </Link>
125	                    </Button>
126	                  </div>
127	                </div>
128	              );
129	            })}
130	          </div>
131	        )}
132	
133	        <Separator />
134	
135	        <p className="text-xs text-muted-foreground">
136	          Score drop alerts are sent to{" "}
137	          <span className="font-medium text-foreground">{userEmail ?? "your email"}</span>{" "}
138	          when a monitored URL drops more than 5 points month-over-month.
139	        </p>
140	      </CardContent>
141	    </Card>
142	  );
143	}
