2	import supabase from "@/lib/supabase";
3	import { useAuth } from "@/contexts/AuthContext";
4	import type { ScanHistoryEntry } from "@/types";
5	
6	// ── Query keys ──────────────────────────────────────────────────
7	
8	export const scanHistoryKeys = {
9	  all: ["scan-history"] as const,
10	  byUrl: (urlHash: string) => ["scan-history", "url", urlHash] as const,
11	  allUrls: (userId: string) => ["scan-history", "all-urls", userId] as const,
12	};
13	
14	// ── Row → App type mapper ────────────────────────────────────────
15	
16	function rowToEntry(row: Record<string, unknown>): ScanHistoryEntry {
17	  return {
18	    id: row.id as string,
19	    user_id: row.user_id as string,
20	    url_hash: row.url_hash as string,
21	    url: row.url as string,
22	    scan_id: row.scan_id as string,
23	    score: row.score as number,
24	    pillar_scores: (row.pillar_scores as ScanHistoryEntry["pillar_scores"]) ?? null,
25	    scanned_at: row.scanned_at as string,
26	  };
27	}
28	
29	// ── useScanHistory ──────────────────────────────────────────────
30	// All entries for a given url_hash, ordered chronologically ASC.
31	
32	export function useScanHistory(urlHash: string) {
33	  const { user } = useAuth();
34	
35	  return useQuery({
36	    queryKey: scanHistoryKeys.byUrl(urlHash),
37	    queryFn: async (): Promise<ScanHistoryEntry[]> => {
38	      if (!urlHash || !user?.id) return [];
39	
40	      const { data, error } = await supabase
41	        .from("scan_history")
42	        .select("*")
43	        .eq("user_id", user.id)
44	        .eq("url_hash", urlHash)
45	        .order("scanned_at", { ascending: true });
46	
47	      if (error) throw new Error(error.message);
48	      return (data as Record<string, unknown>[]).map(rowToEntry);
49	    },
50	    enabled: !!urlHash && !!user?.id,
51	    staleTime: 1000 * 60 * 5,
52	  });
53	}
54	
55	// ── UrlHistoryGroup ─────────────────────────────────────────────
56	
57	export interface UrlHistoryGroup {
58	  url: string;
59	  url_hash: string;
60	  entries: ScanHistoryEntry[];
61	  latestScore: number;
62	  firstScore: number;
63	  delta: number;
64	  latestScanId: string;
65	}
66	
67	// ── useAllUrlHistory ────────────────────────────────────────────
68	// Returns all tracked URLs for the current user, grouped, with deltas.
69	
70	export function useAllUrlHistory() {
71	  const { user } = useAuth();
72	
73	  return useQuery({
74	    queryKey: scanHistoryKeys.allUrls(user?.id ?? ""),
75	    queryFn: async (): Promise<UrlHistoryGroup[]> => {
76	      if (!user?.id) return [];
77	
78	      const { data, error } = await supabase
79	        .from("scan_history")
80	        .select("*")
81	        .eq("user_id", user.id)
82	        .order("scanned_at", { ascending: true });
83	
84	      if (error) throw new Error(error.message);
85	
86	      const rows = (data as Record<string, unknown>[]).map(rowToEntry);
87	
88	      // Group by url_hash
89	      const groupMap = new Map<string, ScanHistoryEntry[]>();
90	      for (const entry of rows) {
91	        const existing = groupMap.get(entry.url_hash);
92	        if (existing) {
93	          existing.push(entry);
94	        } else {
95	          groupMap.set(entry.url_hash, [entry]);
96	        }
97	      }
98	
99	      const groups: UrlHistoryGroup[] = [];
100	      for (const [urlHash, entries] of groupMap) {
101	        // entries are already ASC by scanned_at
102	        const firstEntry = entries[0];
103	        const lastEntry = entries[entries.length - 1];
104	        groups.push({
105	          url: lastEntry.url,
106	          url_hash: urlHash,
107	          entries,
108	          latestScore: lastEntry.score,
109	          firstScore: firstEntry.score,
110	          delta: lastEntry.score - firstEntry.score,
111	          latestScanId: lastEntry.scan_id,
112	        });
113	      }
114	
115	      // Sort groups by latest scan time DESC
116	      groups.sort((a, b) => {
117	        const aLast = a.entries[a.entries.length - 1].scanned_at;
118	        const bLast = b.entries[b.entries.length - 1].scanned_at;
119	        return bLast.localeCompare(aLast);
120	      });
121	
122	      return groups;
123	    },
124	    enabled: !!user?.id,
125	    staleTime: 1000 * 60 * 2,
126	  });
127	}
