import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import supabase from "@/lib/supabase";
import { useAuth } from "@/contexts/AuthContext";
import type { MonitoredUrl, MonitoringFrequency } from "@/types";
import type { MonitoredUrlRow } from "@/types/database";

// ── Query keys ──────────────────────────────────────────────────

export const monitoringKeys = {
  all: ["monitored-urls"] as const,
  byUser: (userId: string) => ["monitored-urls", userId] as const,
};

// ── URL hash helper (mirrors scan_history pattern) ───────────────

export function computeUrlHash(url: string): string {
  return url.trim().toLowerCase();
}

// ── Row → App type mapper ────────────────────────────────────────

function rowToMonitoredUrl(row: MonitoredUrlRow): MonitoredUrl {
  return {
    id: row.id,
    user_id: row.user_id,
    url: row.url,
    url_hash: row.url_hash,
    frequency: row.frequency,
    last_scanned_at: row.last_scanned_at,
    last_score: row.last_score,
    alert_threshold: row.alert_threshold,
    is_active: row.is_active,
    created_at: row.created_at,
  };
}

// ── useMonitoredUrls ────────────────────────────────────────────

export function useMonitoredUrls() {
  const { user } = useAuth();

  return useQuery({
    queryKey: monitoringKeys.byUser(user?.id ?? ""),
    queryFn: async (): Promise<MonitoredUrl[]> => {
      if (!user?.id) return [];

      const { data, error } = await supabase
        .from("monitored_urls")
        .select("*")
        .eq("user_id", user.id)
        .order("created_at", { ascending: false });

      if (error) throw new Error(error.message);
      return (data as MonitoredUrlRow[]).map(rowToMonitoredUrl);
    },
    enabled: !!user?.id,
    staleTime: 1000 * 60 * 2,
  });
}

// ── useAddMonitoredUrl ──────────────────────────────────────────

interface AddMonitoredUrlInput {
  url: string;
  frequency: MonitoringFrequency;
  alert_threshold: number;
}

export function useAddMonitoredUrl() {
  const { user } = useAuth();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (input: AddMonitoredUrlInput): Promise<MonitoredUrl> => {
      if (!user?.id) throw new Error("Not authenticated");

      const url_hash = computeUrlHash(input.url);

      const { data, error } = await supabase
        .from("monitored_urls")
        .insert({
          user_id: user.id,
          url: input.url.trim(),
          url_hash,
          frequency: input.frequency,
          alert_threshold: input.alert_threshold,
          is_active: true,
        })
        .select("*")
        .single();

      if (error) throw new Error(error.message);
      return rowToMonitoredUrl(data as MonitoredUrlRow);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: monitoringKeys.byUser(user?.id ?? "") });
    },
  });
}

// ── useRemoveMonitoredUrl ───────────────────────────────────────

export function useRemoveMonitoredUrl() {
  const { user } = useAuth();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (id: string): Promise<void> => {
      if (!user?.id) throw new Error("Not authenticated");

      const { error } = await supabase
        .from("monitored_urls")
        .delete()
        .eq("id", id)
        .eq("user_id", user.id);

      if (error) throw new Error(error.message);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: monitoringKeys.byUser(user?.id ?? "") });
    },
  });
}

// ── useUpdateMonitoringSettings ─────────────────────────────────

interface UpdateMonitoringSettingsInput {
  id: string;
  frequency?: MonitoringFrequency;
  alert_threshold?: number;
  is_active?: boolean;
}

export function useUpdateMonitoringSettings() {
  const { user } = useAuth();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (input: UpdateMonitoringSettingsInput): Promise<MonitoredUrl> => {
      if (!user?.id) throw new Error("Not authenticated");

      const { id, ...updates } = input;

      const { data, error } = await supabase
        .from("monitored_urls")
        .update(updates)
        .eq("id", id)
        .eq("user_id", user.id)
        .select("*")
        .single();

      if (error) throw new Error(error.message);
      return rowToMonitoredUrl(data as MonitoredUrlRow);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: monitoringKeys.byUser(user?.id ?? "") });
    },
  });
}

// ── useIsMonitored ──────────────────────────────────────────────

export function useIsMonitored(urlHash: string): boolean {
  const { data: monitoredUrls = [] } = useMonitoredUrls();
  return monitoredUrls.some((m) => m.url_hash === urlHash && m.is_active);
}

/**
 * monitor-scheduler — Edge Function (Cron / Internal)
 *
 * Processes all active monitored URLs that are due for a re-scan.
 * Called daily by an external scheduler (e.g. Supabase cron or Railway cron).
 *
 * Auth: service_role key only — no user JWT required.
 *
 * Required env vars:
 *   SUPABASE_URL
 *   SUPABASE_SERVICE_ROLE_KEY
 *   SITE_URL — base URL for invoking other edge functions (e.g. https://xxx.supabase.co)
 */

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

// ── Types ─────────────────────────────────────────────────────

type MonitoringFrequency = "daily" | "weekly" | "monthly";

interface MonitoredUrlRow {
  id: string;
  user_id: string;
  url: string;
  frequency: MonitoringFrequency;
  last_scanned_at: string | null;
  last_score: number | null;
  alert_threshold: number;
}

interface ProfileRow {
  email: string;
  full_name: string;
}

// ── Helpers ───────────────────────────────────────────────────

function isDue(row: MonitoredUrlRow): boolean {
  if (!row.last_scanned_at) return true;

  const last = new Date(row.last_scanned_at).getTime();
  const now = Date.now();
  const diffHours = (now - last) / (1000 * 60 * 60);

  switch (row.frequency) {
    case "daily":
      return diffHours >= 24;
    case "weekly":
      return diffHours >= 24 * 7;
    case "monthly":
      return diffHours >= 24 * 30;
    default:
      return false;
  }
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

// ── Main handler ──────────────────────────────────────────────

serve(async (req) => {
  // Only allow POST (called by cron with optional bearer header)
  if (req.method !== "POST") {
    return new Response(JSON.stringify({ error: "Method not allowed" }), {
      status: 405,
      headers: { "Content-Type": "application/json" },
    });
  }

  const supabaseUrl = Deno.env.get("SUPABASE_URL") ?? "";
  const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "";

  const supabase = createClient(supabaseUrl, serviceRoleKey, {
    auth: { persistSession: false },
  });

  // ── 1. Fetch active monitored URLs ─────────────────────────

  const { data: rows, error: fetchError } = await supabase
    .from("monitored_urls")
    .select("id, user_id, url, frequency, last_scanned_at, last_score, alert_threshold")
    .eq("is_active", true);

  if (fetchError) {
    return new Response(
      JSON.stringify({ error: "Failed to fetch monitored URLs", detail: fetchError.message }),
      { status: 500, headers: { "Content-Type": "application/json" } }
    );
  }

  const dueRows = (rows as MonitoredUrlRow[]).filter(isDue);

  const results: Array<{ id: string; url: string; status: string; error?: string }> = [];

  // ── 2. Process each due URL ────────────────────────────────

  for (const row of dueRows) {
    await sleep(500); // Rate-limit between URLs

    try {
      // ── 2a. Invoke analyze-url ───────────────────────────────
      const analyzeRes = await fetch(
        `${supabaseUrl}/functions/v1/analyze-url`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${serviceRoleKey}`,
            "x-monitor-user-id": row.user_id,
          },
          body: JSON.stringify({
            url: row.url,
            page_type: "landing",
            monitor_user_id: row.user_id,
          }),
        }
      );

      if (!analyzeRes.ok) {
        const errText = await analyzeRes.text();
        throw new Error(`analyze-url returned ${analyzeRes.status}: ${errText}`);
      }

      const analyzeData = (await analyzeRes.json()) as { scan_id?: string };
      const scanId = analyzeData.scan_id;

      if (!scanId) {
        throw new Error("analyze-url did not return a scan_id");
      }

      // ── 2b. Fetch new scan score ─────────────────────────────
      // Poll for up to 90s (18 × 5s) since AI analysis can take time
      let newScore: number | null = null;
      for (let attempt = 0; attempt < 18; attempt++) {
        await sleep(5000);

        const { data: scanRow, error: scanErr } = await supabase
          .from("scans")
          .select("overall_score, status")
          .eq("id", scanId)
          .single();

        if (scanErr) break;

        const scan = scanRow as { overall_score: number | null; status: string };

        if (scan.status === "completed" && scan.overall_score !== null) {
          newScore = scan.overall_score;
          break;
        }
        if (scan.status === "failed") break;
      }

      // ── 2c. Check threshold and send alert ──────────────────
      if (
        newScore !== null &&
        row.last_score !== null &&
        row.last_score - newScore >= row.alert_threshold
      ) {
        const drop = row.last_score - newScore;

        // Fetch user profile for email
        const { data: profileData } = await supabase
          .from("profiles")
          .select("email, full_name")
          .eq("id", row.user_id)
          .single();

        const profile = profileData as ProfileRow | null;

        if (profile?.email) {
          // Send score drop alert email
          await fetch(`${supabaseUrl}/functions/v1/send-email`, {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
              Authorization: `Bearer ${serviceRoleKey}`,
            },
            body: JSON.stringify({
              type: "score_drop_alert",
              to: profile.email,
              data: {
                name: profile.full_name ?? "there",
                url: row.url,
                previous_score: row.last_score,
                new_score: newScore,
                drop,
                scan_id: scanId,
              },
            }),
          }).catch(() => {
            // Non-fatal — email failure should not block monitoring update
          });

          // Insert in-app notification
          await supabase.from("notifications").insert({
            user_id: row.user_id,
            type: "score_drop" as const,
            title: `Score dropped on ${new URL(row.url).hostname}`,
            body: `Your CRO score dropped by ${drop} points (${row.last_score} → ${newScore}).`,
            link: `/reports/${scanId}`,
          }).catch(() => {
            // Non-fatal
          });
        }
      }

      // ── 2d. Update monitored_urls record ─────────────────────
      await supabase
        .from("monitored_urls")
        .update({
          last_scanned_at: new Date().toISOString(),
          ...(newScore !== null ? { last_score: newScore } : {}),
        })
        .eq("id", row.id);

      results.push({ id: row.id, url: row.url, status: newScore !== null ? "scanned" : "scan_pending" });
    } catch (err) {
      // Non-fatal — log and continue to next URL
      const message = err instanceof Error ? err.message : String(err);
      results.push({ id: row.id, url: row.url, status: "error", error: message });
    }
  }

  return new Response(
    JSON.stringify({
      processed: dueRows.length,
      results,
    }),
    { status: 200, headers: { "Content-Type": "application/json" } }
  );
});

