// ── Helpers ────────────────────────────────────────────────────

function getNextScanDate(entry: MonitoredUrl): string {
  if (!entry.last_scanned_at) return "Soon";

  const last = new Date(entry.last_scanned_at);
  const next = new Date(last);

  switch (entry.frequency) {
    case "daily":
      next.setDate(next.getDate() + 1);
      break;
    case "weekly":
      next.setDate(next.getDate() + 7);
      break;
    case "monthly":
      next.setDate(next.getDate() + 30);
      break;
  }

  const now = new Date();
  if (next <= now) return "Due now";

  return next.toLocaleDateString("en-US", { month: "short", day: "numeric" });
}

function truncateUrl(url: string, maxLen = 42): string {
  try {
    const { hostname, pathname } = new URL(url);
    const display = hostname.replace("www.", "") + pathname;
    return display.length > maxLen ? display.slice(0, maxLen) + "…" : display;
  } catch {
    return url.length > maxLen ? url.slice(0, maxLen) + "…" : url;
  }
}

