interface MonitoredUrlCardProps {
  entry: MonitoredUrl;
  onRemove: (id: string) => void;
  isRemoving: boolean;
}

function MonitoredUrlCard({ entry, onRemove, isRemoving }: MonitoredUrlCardProps) {
  const updateSettings = useUpdateMonitoringSettings();
  const [localFrequency, setLocalFrequency] = useState<MonitoringFrequency>(entry.frequency);
  const [localThreshold, setLocalThreshold] = useState(String(entry.alert_threshold));
  const [showSettings, setShowSettings] = useState(false);

  const handleToggleActive = (checked: boolean) => {
    updateSettings.mutate(
      { id: entry.id, is_active: checked },
      {
        onSuccess: () => toast.success(checked ? "Monitoring enabled" : "Monitoring paused"),
        onError: () => toast.error("Failed to update monitoring status"),
      }
    );
  };

  const handleSaveSettings = () => {
    const threshold = parseInt(localThreshold, 10);
    if (isNaN(threshold) || threshold < 1 || threshold > 20) {
      toast.error("Threshold must be between 1 and 20");
      return;
    }

    updateSettings.mutate(
      { id: entry.id, frequency: localFrequency, alert_threshold: threshold },
      {
        onSuccess: () => {
          toast.success("Settings updated");
          setShowSettings(false);
        },
        onError: () => toast.error("Failed to update settings"),
      }
    );
  };

  const nextScan = getNextScanDate(entry);

  return (
    <Card className="overflow-hidden">
      <CardContent className="p-5">
        <div className="flex items-start justify-between gap-4">
          {/* Left: score ring + URL info */}
          <div className="flex items-center gap-3 min-w-0">
            {entry.last_score !== null ? (
              <ScoreRing
                score={entry.last_score}
                size={40}
                strokeWidth={4}
                showLabel={false}
                className="shrink-0"
              />
            ) : (
              <div className="flex h-10 w-10 items-center justify-center rounded-full bg-muted shrink-0">
                <Activity className="h-4 w-4 text-muted-foreground" />
              </div>
            )}

            <div className="min-w-0">
              <div className="flex items-center gap-1.5">
                <p className="text-sm font-medium truncate">{truncateUrl(entry.url)}</p>
                <a
                  href={entry.url}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="shrink-0 text-muted-foreground hover:text-foreground transition-colors"
                  aria-label="Open URL in new tab"
                >
                  <ExternalLink className="h-3.5 w-3.5" />
                </a>
              </div>
              <div className="mt-0.5 flex items-center gap-2 flex-wrap">
                <Badge variant="secondary" className="text-2xs px-1.5 py-0 h-4">
                  {FREQUENCY_LABELS[entry.frequency]}
                </Badge>
                <span className="text-xs text-muted-foreground flex items-center gap-1">
                  <CalendarClock className="h-3 w-3" />
                  Next: {nextScan}
                </span>
                {entry.last_score !== null && (
                  <span className="text-xs text-muted-foreground">
                    Score: {entry.last_score}
                  </span>
                )}
              </div>
            </div>
          </div>

          {/* Right: active toggle */}
          <div className="flex items-center gap-2 shrink-0">
            <Switch
              checked={entry.is_active}
              onCheckedChange={handleToggleActive}
              disabled={updateSettings.isPending}
              aria-label="Toggle monitoring active"
            />
          </div>
        </div>

        {/* Settings row */}
        <div className="mt-4 flex items-center gap-2 flex-wrap">
          <Button
            variant="outline"
            size="sm"
            onClick={() => setShowSettings(!showSettings)}
            className="h-8 text-xs"
          >
            <Settings2 className="mr-1.5 h-3.5 w-3.5" />
            Settings
          </Button>
          <Button
            variant="ghost"
            size="sm"
            onClick={() => onRemove(entry.id)}
            disabled={isRemoving}
            className="h-8 text-xs text-destructive hover:text-destructive hover:bg-destructive/10"
            aria-label="Remove from monitoring"
          >
            {isRemoving ? (
              <Loader2 className="h-3.5 w-3.5 animate-spin" />
            ) : (
              <Trash2 className="h-3.5 w-3.5" />
            )}
          </Button>
        </div>

        {/* Inline settings panel */}
        <AnimatePresence>
          {showSettings && (
            <motion.div
              initial={{ opacity: 0, height: 0 }}
              animate={{ opacity: 1, height: "auto" }}
              exit={{ opacity: 0, height: 0 }}
              transition={{ duration: 0.2 }}
              className="overflow-hidden"
            >
              <div className="mt-4 border-t border-border/60 pt-4 grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <Label className="text-xs text-muted-foreground">Frequency</Label>
                  <Select
                    value={localFrequency}
                    onValueChange={(v) => setLocalFrequency(v as MonitoringFrequency)}
