interface AddUrlDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

function AddUrlDialog({ open, onOpenChange }: AddUrlDialogProps) {
  const addUrl = useAddMonitoredUrl();
  const [url, setUrl] = useState("");
  const [frequency, setFrequency] = useState<MonitoringFrequency>("weekly");
  const [threshold, setThreshold] = useState("5");

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    const trimmed = url.trim();
    if (!trimmed) {
      toast.error("URL is required");
      return;
    }

    try {
      new URL(trimmed); // validate URL format
    } catch {
      toast.error("Please enter a valid URL (e.g. https://example.com)");
      return;
    }

    const thresholdNum = parseInt(threshold, 10);
    if (isNaN(thresholdNum) || thresholdNum < 1 || thresholdNum > 20) {
      toast.error("Threshold must be between 1 and 20");
      return;
    }

    addUrl.mutate(
      { url: trimmed, frequency, alert_threshold: thresholdNum },
      {
        onSuccess: () => {
          toast.success("URL added to monitoring");
          setUrl("");
          setFrequency("weekly");
          setThreshold("5");
          onOpenChange(false);
        },
        onError: (err) => {
          toast.error(err instanceof Error ? err.message : "Failed to add URL");
        },
      }
    );
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>Add URL to Monitor</DialogTitle>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4 py-2">
          <div className="space-y-1.5">
            <Label htmlFor="monitor-url">URL</Label>
            <Input
              id="monitor-url"
              type="url"
              placeholder="https://yoursite.com/landing"
              value={url}
              onChange={(e) => setUrl(e.target.value)}
              required
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1.5">
              <Label htmlFor="monitor-frequency">Frequency</Label>
              <Select
                value={frequency}
                onValueChange={(v) => setFrequency(v as MonitoringFrequency)}
              >
                <SelectTrigger id="monitor-frequency">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="daily">Daily</SelectItem>
                  <SelectItem value="weekly">Weekly</SelectItem>
                  <SelectItem value="monthly">Monthly</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-1.5">
              <Label htmlFor="monitor-threshold">Alert if drop &ge;</Label>
              <Input
                id="monitor-threshold"
                type="number"
                min={1}
                max={20}
                value={threshold}
                onChange={(e) => setThreshold(e.target.value)}
                placeholder="5"
              />
            </div>
          </div>

          <p className="text-xs text-muted-foreground">
            You'll receive an email alert when the CRO score drops by{" "}
            <span className="font-medium">{threshold || "—"} or more points</span>.
          </p>

          <DialogFooter>
            <Button type="button" variant="outline" onClick={() => onOpenChange(false)}>
              Cancel
            </Button>
            <Button type="submit" disabled={addUrl.isPending}>
              {addUrl.isPending ? (
                <>
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                  Adding…
                </>
              ) : (
                "Add URL"
              )}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

