        </CardHeader>
        <CardContent>
          <div className="rounded-lg bg-muted/40 p-4 text-sm text-muted-foreground">
            Upgrade to Pro to enable daily, weekly, or monthly score monitoring and receive email
            alerts when CRO scores drop below your threshold.
          </div>
          <Button className="mt-4 w-full" asChild>
            <Link to="/pricing">Upgrade to Pro</Link>
          </Button>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className="border-border/50 shadow-none">
      <CardHeader>
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Bell className="h-4 w-4 text-muted-foreground" />
            <CardTitle className="text-base">Score Monitoring</CardTitle>
          </div>
          <Button variant="ghost" size="sm" className="h-7 gap-1 text-xs" asChild>
            <Link to="/monitoring">
              Manage
              <ArrowRight className="h-3 w-3" />
            </Link>
          </Button>
        </div>
        {isLoading ? (
          <Skeleton className="h-4 w-48 mt-1" />
        ) : (
          <CardDescription>
            {activeUrls.length} URL{activeUrls.length !== 1 ? "s" : ""} being monitored.
            {monitoredUrls.length > activeUrls.length && (
              <> {monitoredUrls.length - activeUrls.length} paused.</>
            )}
          </CardDescription>
        )}
      </CardHeader>

      <CardContent className="space-y-4">
        {isLoading ? (
          <div className="space-y-3">
            {[1, 2].map((i) => (
              <div key={i} className="flex items-center justify-between">
                <Skeleton className="h-4 w-36" />
                <Skeleton className="h-4 w-20" />
              </div>
            ))}
          </div>
        ) : activeUrls.length === 0 ? (
          <div className="rounded-lg border border-dashed border-border/60 p-6 text-center">
            <Bell className="mx-auto h-8 w-8 text-muted-foreground/40 mb-2" />
            <p className="text-sm text-muted-foreground">No URLs monitored yet.</p>
            <Button variant="outline" size="sm" className="mt-3 border-border/50" asChild>
              <Link to="/monitoring">Start Monitoring</Link>
            </Button>
          </div>
        ) : (
          <div className="divide-y divide-border/50">
            {activeUrls.slice(0, 3).map((entry) => {
              let hostname = entry.url;
              try {
                hostname = new URL(entry.url).hostname.replace("www.", "");
              } catch {
                /* keep raw url */
              }

              const nextScan = getNextScanDate(entry);

              return (
                <div
                  key={entry.id}
                  className="flex items-center justify-between py-3 first:pt-0 last:pb-0"
                >
                  <div className="flex items-center gap-2 min-w-0">
                    <Bell className="h-3.5 w-3.5 shrink-0 text-primary" />
                    <div className="min-w-0">
                      <span className="text-sm truncate block">{hostname}</span>
                      <span className="text-xs text-muted-foreground capitalize">
                        {entry.frequency} · drops {entry.alert_threshold}+ pts
                      </span>
                    </div>
                  </div>
                  <div className="flex items-center gap-2 shrink-0">
                    <div className="flex items-center gap-1 text-xs text-muted-foreground">
                      <Calendar className="h-3 w-3" />
                      <span>{nextScan}</span>
                    </div>
                  </div>
                </div>
              );
            })}
            {activeUrls.length > 3 && (
              <div className="pt-3">
                <Button variant="ghost" size="sm" className="h-7 w-full text-xs" asChild>
                  <Link to="/monitoring">
                    View all {activeUrls.length} URLs
                    <ArrowRight className="ml-1 h-3 w-3" />
                  </Link>
                </Button>
              </div>
            )}
          </div>
        )}

        {!isLoading && activeUrls.length > 0 && (
          <>
            <Separator />
            <p className="text-xs text-muted-foreground">
              Score drop alerts are sent to{" "}
              <span className="font-medium text-foreground">{userEmail ?? "your email"}</span>.
            </p>
          </>
        )}
      </CardContent>
    </Card>
  );
}

